-- Insert a record
INSERT INTO patients (first_name, last_name, gender, birth_date, city, province_id, allergies, weight, height)
VALUES ('John', 'Smith', 'M', '1994-02-21', 'Hamilton', 'ON', NULL, 132, 182);

-- Select the most recent record by id
SELECT * FROM patients
WHERE patient_id = (SELECT MAX(patient_id) FROM patients);

-- Insert a record
INSERT INTO patients (first_name, last_name, gender)
VALUES ('Jane', 'Doe', 'F');

-- Select the most recent record by id
SELECT * FROM patients
WHERE patient_id = (SELECT MAX(patient_id) FROM patients);

DELETE FROM patients WHERE first_name = 'Paul';

-- There are no longer any patients named 'Paul' in the database

SELECT * FROM patients WHERE first_name = 'Paul';

UPDATE tablename
SET column1 = value1, column2 = value2, ...
WHERE condition;

UPDATE patients
SET allergies = 'NKA'
WHERE allergies IS NULL;

-- display the patients table
SELECT * FROM patients;

SELECT column1, column2, ...
FROM tablename
WHERE condition;

SELECT * FROM patients
WHERE patient_id <> 5;

-- No patient_id 5 row

SELECT * FROM patients
WHERE patient_id IN (1, 3, 6, 9);

-- the values can be replaced with a sub-query.

SELECT column1, column2, ...
FROM table_name
WHERE condition1 AND condition2 AND condition3 ...;

SELECT column1, column2, ...
FROM table_name
WHERE condition1 OR condition2 OR condition3 ...;

SELECT column1, column2, ...
FROM table_name
WHERE NOT condition;

SELECT column1, column2, ...
FROM table_name
ORDER BY column1, column2, ... ASC|DESC;

SELECT column1, column2, ...
FROM table_name
WHERE column LIKE pattern;

-- Finds any values that start with "a"
WHERE first_name LIKE 'a%';

-- Finds any values that end with "a"
WHERE first_name LIKE '%a';

-- Finds any values that have "or" in any position
WHERE first_name LIKE '%or%';

-- Finds any values that have "r" in the second position
WHERE first_name LIKE '_r%';

-- Finds any values that start with "a" and are at least 2 characters
WHERE first_name LIKE 'a_%';

-- Finds any values that start with "a" and are at least 3 characters
WHERE first_name LIKE 'a__%';

-- Finds any values that start with "a" and ends with "o"
WHERE first_name LIKE 'a%o';

SELECT column_name(s)
FROM table_name
WHERE column_name IN (value1, value2, ...);

SELECT column_name(s)
FROM table_name
WHERE column_name IN (SELECT STATEMENT);

SELECT * FROM patients
WHERE first_name IN (SELECT first_name FROM doctors);

-- Try running just the sub query to see the list

SELECT column_name(s) 
FROM table_name
WHERE column_name BETWEEN value1 AND value2;

SELECT * FROM patients
WHERE weight BETWEEN 100 AND 120
AND province_id NOT IN ('ON', 'SK', 'AB');

SELECT *
FROM patients p
JOIN admissions a ON a.patient_id = p.patient_id;

SELECT column_name(s) FROM table1
UNION
SELECT column_name(s) FROM table2;

SELECT column_name(s) FROM table1
UNION ALL
SELECT column_name(s) FROM table2;

SELECT COUNT(*), province_id
FROM patients
GROUP BY province_id;

SELECT * FROM patients
JOIN admissions ON patients.patient_id = admissions.patient_id
WHERE diagnosis = 'Pregnancy';

SELECT ALL column_name(s)
FROM table_name
WHERE condition;

SELECT column_names
FROM table_name
WHERE column_name IS NULL;

SELECT column_names
FROM table_name
WHERE column_name IS NOT NULL;

SELECT *
FROM patients
WHERE allergies IS NULL;

SELECT avg(weight) AS average_weight,
       avg(height) AS average_height
FROM patients;

SELECT *
FROM patients AS p
  JOIN admissions AS a ON a.patient_id = p.patient_id;

SELECT COUNT(column_name)
FROM table_name
WHERE condition;

SELECT COUNT(*) 
FROM patients 
WHERE weight > 120;

SELECT AVG(column_name)
FROM table_name
WHERE condition;

SELECT SUM(column_name)
FROM table_name
WHERE condition;

SELECT MAX(column_name)
FROM table_name
WHERE condition;

SELECT MIN(column_name)
FROM table_name
WHERE condition;

CREATE TABLE table_name (
    column1 datatype,
    column2 datatype,
    column3 datatype,
    ...
);

CREATE TABLE TestPatients AS
SELECT patient_id, first_name, last_name
FROM patients;

-- Verify the new table
SELECT * FROM TestPatients;

DROP TABLE patients;

-- Attempt to query the table after dropping it
SELECT * FROM patients;

ALTER TABLE patients
ADD email varchar(255);

SELECT patient_id, email FROM patients;

ALTER TABLE patients
DROP COLUMN last_name;

SELECT * FROM patients;

-- SQL Server / MS Access
ALTER TABLE table_name
ALTER COLUMN column_name datatype;

-- MySQL / Oracle (prior to 10G)
ALTER TABLE table_name
MODIFY COLUMN column_name datatype;

-- Oracle 10G and later
ALTER TABLE table_name
MODIFY column_name datatype;

CREATE TABLE table_name (
    column1 datatype constraint,
    column2 datatype constraint,
    column3 datatype constraint,
    ....
);

CREATE TABLE Persons (
    ID int NOT NULL,
    LastName varchar(255) NOT NULL,
    FirstName varchar(255) NOT NULL,
    Age int
);

-- SQL Server / Oracle / MS Access
CREATE TABLE Persons (
    ID int NOT NULL UNIQUE,
    LastName varchar(255) NOT NULL,
    FirstName varchar(255),
    Age int
);

-- display the empty table Persons
SELECT * FROM Persons;

-- MySQL / SQL Server / Oracle / MS Access
ALTER TABLE Persons
ADD UNIQUE (ID);

-- Naming or multiple columns
ALTER TABLE Persons
ADD CONSTRAINT UC_Person UNIQUE (ID, LastName);

-- MySQL
ALTER TABLE Persons
DROP INDEX UC_Person;

-- SQL Server / Oracle / MS Access
ALTER TABLE Persons
DROP CONSTRAINT UC_Person;

-- MySQL / SQL Server / Oracle / MS Access
ALTER TABLE Persons
ADD PRIMARY KEY (ID);

-- Naming or multiple columns
ALTER TABLE Persons
ADD CONSTRAINT PK_Person PRIMARY KEY (ID, LastName);

-- MySQL
ALTER TABLE Persons
DROP PRIMARY KEY;

-- SQL Server / Oracle / MS Access
ALTER TABLE Persons
DROP CONSTRAINT PK_Person;

-- SQL Server / Oracle / MS Access
CREATE TABLE Orders (
    OrderID int NOT NULL PRIMARY KEY,
    OrderNumber int NOT NULL,
    PersonID int FOREIGN KEY REFERENCES Persons(PersonID)
);

-- MySQL
ALTER TABLE Orders
DROP FOREIGN KEY FK_PersonOrder;

-- SQL Server / Oracle / MS Access
ALTER TABLE Orders
DROP CONSTRAINT FK_PersonOrder;

-- MySQL / SQL Server / Oracle / MS Access
ALTER TABLE Persons
ADD CHECK (Age>=18);

-- Naming or multiple columns
ALTER TABLE Persons
ADD CONSTRAINT CHK_PersonAge CHECK (Age>=18 AND City='Sandnes');

-- MySQL
ALTER TABLE Persons
DROP CHECK CHK_PersonAge;

-- SQL Server / Oracle / MS Access
ALTER TABLE Persons
DROP CONSTRAINT CHK_PersonAge;

-- MySQL / SQL Server / Oracle / MS Access
CREATE TABLE Orders (
    ID int NOT NULL,
    OrderNumber int NOT NULL,
    OrderDate date DEFAULT current_timestamp
);

-- Example insert
INSERT INTO Orders (ID, OrderNumber) VALUES (1,1);

SELECT * FROM Orders;

-- MySQL
ALTER TABLE Persons
ALTER City SET DEFAULT 'Sandnes';

-- SQL Server
ALTER TABLE Persons
ADD CONSTRAINT df_City
DEFAULT 'Sandnes' FOR City;

-- MS Access
ALTER TABLE Persons
ALTER COLUMN City SET DEFAULT 'Sandnes';

-- Oracle
ALTER TABLE Persons
MODIFY City DEFAULT 'Sandnes';

-- MySQL
ALTER TABLE Persons
ALTER City DROP DEFAULT;

-- SQL Server / Oracle / MS Access
ALTER TABLE Persons
ALTER COLUMN City DROP DEFAULT;

CREATE TABLE Persons (
    Personid int NOT NULL AUTO_INCREMENT,
    LastName varchar(255) NOT NULL,
    FirstName varchar(255),
    Age int,
    PRIMARY KEY (Personid)
);

-- Start AUTO_INCREMENT with another value
ALTER TABLE Persons AUTO_INCREMENT=100;

-- Insert without specifying Personid
INSERT INTO Persons (FirstName, LastName)
VALUES ('Lars','Monsen');

CREATE TABLE Persons (
    Personid int IDENTITY(1,1) PRIMARY KEY,
    LastName varchar(255) NOT NULL,
    FirstName varchar(255),
    Age int
);

-- Tip: Start at 10, increment by 5
-- Personid int IDENTITY(10,5) PRIMARY KEY

INSERT INTO Persons (FirstName, LastName)
VALUES ('Lars','Monsen');

CREATE TABLE Persons (
    Personid AUTOINCREMENT PRIMARY KEY,
    LastName varchar(255) NOT NULL,
    FirstName varchar(255),
    Age int
);

-- Tip: Start at 10, increment by 5
-- AUTOINCREMENT(10,5)

INSERT INTO Persons (FirstName, LastName)
VALUES ('Lars','Monsen');

-- Creates a regular index (duplicate values allowed)
CREATE INDEX index_name
ON table_name (column1, column2, ...);

-- Creates a unique index (duplicate values not allowed)
CREATE UNIQUE INDEX index_name
ON table_name (column1, column2, ...);

-- MS Access
DROP INDEX index_name ON table_name;

-- SQL Server
DROP INDEX table_name.index_name;

-- DB2 / Oracle
DROP INDEX index_name;

-- MySQL
ALTER TABLE table_name
DROP INDEX index_name;
